'use client';

import { MotionNumber } from '@/components/core/motion-number';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import {
  pressedQuietOf,
  spokenUnless,
} from '@/registry/ndeko/lib/demonstration';
import { GaugeIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { Fold, Swap } from '@/registry/ndeko/ui/chat-motion';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';
import { Tabs, TabsList, TabsTab } from '@/registry/ndeko/ui/tabs';

import { DayChart } from './day-chart';
import {
  isNearLimit,
  PERIODS,
  percentOf,
  periodOf,
  shareOf,
  USAGE,
  usedOf,
  WORKSPACE,
} from './data';
import { LimitRows } from './limit-rows';
import { INITIAL, LOOP_AFTER_MS, reducer, RESTING, SCRIPT } from './session';
import { ModelLegend, UsageBar } from './usage-bar';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

const SURFACE =
  'bg-card hairline-ring ring-border dark:bg-foreground/[0.03] rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]';

type Standing = {
  variant: 'warning' | 'success';
  label: string;
};

const NEAR_LIMIT: Standing = { variant: 'warning', label: 'Near the limit' };

const WITHIN_PLAN: Standing = { variant: 'success', label: 'Within the plan' };

function standingOf(isNear: boolean) {
  if (isNear) {
    return NEAR_LIMIT;
  }
  return WITHIN_PLAN;
}

export default function AiProduct01() {
  const { ref, isAutoplaying, state, act, pressed, isFinished, restart } =
    useSession(SESSION);
  useKeptHeight(ref);
  const { period, hasChanged } = state;
  const usage = USAGE[period];
  const used = usedOf(usage);
  const share = shareOf(used, usage.limit);
  const isNear = isNearLimit(share);
  const standing = standingOf(isNear);
  const shown = periodOf(period);
  const hasUpgrade = usage.upgrade !== null;
  const upgradeLine = usage.upgrade ?? USAGE.month.upgrade ?? '';
  const message = spokenUnless(isAutoplaying, state.spoken);
  const canReplay = isFinished && !isAutoplaying;

  function pickPeriod(value: unknown) {
    const picked = PERIODS.find((candidate) => candidate.id === value);
    if (picked) {
      act({ type: 'periodPicked', period: picked.id });
    }
  }

  return (
    <div
      ref={ref}
      className='bg-background text-foreground @container min-h-[46rem] w-full @3xl:min-h-[40rem]'
    >
      <div className='mx-auto flex max-w-4xl flex-col gap-5 px-4 py-8 @2xl:px-6 @2xl:py-12'>
        <header className='flex flex-wrap items-center justify-between gap-x-4 gap-y-3'>
          <div className='flex min-w-0 items-center gap-2.5'>
            <CompanyMark seed={WORKSPACE.name} size='lg' />
            <div className='flex min-w-0 flex-col'>
              <h2 className='truncate text-sm font-medium'>Usage and limits</h2>
              <p className='text-muted-foreground flex items-center gap-1.5 text-xs'>
                {WORKSPACE.name}, {WORKSPACE.plan}
                <Badge variant='secondary'>Illustrative</Badge>
              </p>
            </div>
          </div>
          <div className='flex items-center gap-2'>
            <ReplayButton
              isShown={canReplay}
              onReplay={restart}
              label='Replay'
            />
            <Tabs value={period} onValueChange={pickPeriod}>
              <TabsList variant='segmented' aria-label='Period'>
                {PERIODS.map((candidate) => (
                  <TabsTab
                    key={candidate.id}
                    value={candidate.id}
                    className={cn(
                      'text-xs transition-[color,background-color,scale]',
                      pressedQuietOf(pressed === `period-${candidate.id}`)
                    )}
                  >
                    {candidate.label}
                  </TabsTab>
                ))}
              </TabsList>
            </Tabs>
          </div>
        </header>

        <section
          aria-label='Credits used'
          className={cn(SURFACE, 'flex flex-col gap-5 p-5 @2xl:p-6')}
        >
          <div className='flex flex-wrap items-end justify-between gap-x-4 gap-y-2'>
            <div className='flex flex-col gap-1'>
              <p className='text-muted-foreground flex items-center gap-1.5 text-[13px] font-medium'>
                <GaugeIcon className='size-4' />
                Credits used {shown.spoken}
              </p>
              <p className='flex items-baseline gap-2'>
                <MotionNumber
                  value={used}
                  className='text-3xl font-semibold @2xl:text-4xl'
                />
                <span className='text-muted-foreground flex items-baseline gap-1 text-[13px]'>
                  of
                  <MotionNumber value={usage.limit} />
                </span>
              </p>
            </div>
            <div className='flex items-center gap-2'>
              <span className='flex items-baseline text-[13px] tabular-nums'>
                <MotionNumber value={percentOf(share)} suffix='%' />
              </span>
              <Swap swapKey={standing.label}>
                <Badge variant={standing.variant}>{standing.label}</Badge>
              </Swap>
            </div>
          </div>
          <UsageBar
            periodId={period}
            limit={usage.limit}
            used={used}
            byModel={usage.byModel}
            hasChanged={hasChanged}
          />
          <ModelLegend byModel={usage.byModel} />
          <Fold open={hasUpgrade}>
            <div className='bg-foreground/[0.04] flex flex-wrap items-center justify-between gap-x-4 gap-y-2 rounded-lg p-3'>
              <p className='min-w-0 flex-1 text-[13px] text-pretty'>
                {upgradeLine}
              </p>
              <Button type='button' size='sm' variant='outline'>
                Compare plans
              </Button>
            </div>
          </Fold>
        </section>

        <div className='grid gap-5 @3xl:grid-cols-[minmax(0,1.3fr)_minmax(0,1fr)]'>
          <section
            aria-label={shown.chartTitle}
            className={cn(SURFACE, 'flex flex-col gap-4 p-5 @2xl:p-6')}
          >
            <h3 className='text-sm font-medium'>
              <Swap swapKey={shown.chartTitle}>{shown.chartTitle}</Swap>
            </h3>
            <DayChart
              periodId={period}
              values={usage.chart}
              labels={shown.chartLabels}
              caption={`${shown.chartTitle}, illustrative`}
              hasChanged={hasChanged}
            />
          </section>
          <section
            aria-label='Plan limits'
            className={cn(SURFACE, 'flex flex-col gap-4 p-5 @2xl:p-6')}
          >
            <h3 className='text-sm font-medium'>Plan limits</h3>
            <LimitRows />
          </section>
        </div>
      </div>
      <LiveRegion message={message} />
    </div>
  );
}

'use client';

import { motion, type Transition } from 'motion/react';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { EASE_OUT_STRONG, INSTANT } from '@/registry/ndeko/lib/motion-presets';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';

import { MODELS, shareOf, type ModelId, type PeriodId } from './data';

const STAGGER_S = 0.07;

const FILL_S = 0.7;

type Layer = {
  id: ModelId;
  color: string;
  share: number;
  delay: number;
};

/** The segments overlap, longest at the bottom: each layer reaches the end of its model, so the one on top is the first segment. */
function layersOf(byModel: Record<ModelId, number>, limit: number) {
  const layers: Layer[] = [];
  let running = 0;
  for (const [index, model] of MODELS.entries()) {
    running += byModel[model.id];
    layers.push({
      id: model.id,
      color: seriesColorOf(model.series),
      share: shareOf(running, limit),
      delay: index * STAGGER_S,
    });
  }
  return [...layers].reverse();
}

function fillOf(shouldReduceMotion: boolean, delay: number): Transition {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return { duration: FILL_S, ease: EASE_OUT_STRONG, delay };
}

function startOf(hasChanged: boolean, shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return false;
  }
  if (hasChanged) {
    return { scaleX: 0 };
  }
  return false;
}

export function creditsText(value: number) {
  return value.toLocaleString('en-US');
}

type UsageBarProps = {
  periodId: PeriodId;
  limit: number;
  used: number;
  byModel: Record<ModelId, number>;
  hasChanged: boolean;
};

export function UsageBar({
  periodId,
  limit,
  used,
  byModel,
  hasChanged,
}: UsageBarProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const layers = layersOf(byModel, limit);
  const initial = startOf(hasChanged, shouldReduceMotion);
  const usedText = creditsText(used);
  const limitText = creditsText(limit);
  const label = `${usedText} of ${limitText} credits used`;

  return (
    <div className='relative flex flex-col gap-1.5'>
      <p className='text-muted-foreground flex items-baseline justify-end gap-1 text-xs'>
        Limit
        <MotionNumber value={limit} className='text-foreground' />
      </p>
      <div className='relative'>
        <div
          role='img'
          aria-label={label}
          className='bg-foreground/[0.06] relative h-3 overflow-hidden rounded-full'
        >
          {layers.map((layer) => (
            <motion.span
              key={`${periodId}-${layer.id}`}
              initial={initial}
              animate={{ scaleX: layer.share }}
              transition={fillOf(shouldReduceMotion, layer.delay)}
              style={{ backgroundColor: layer.color }}
              className='absolute inset-0 origin-left'
            />
          ))}
        </div>
        <span
          aria-hidden='true'
          className='bg-foreground/40 absolute end-0 -top-1 -bottom-1 w-px'
        />
      </div>
    </div>
  );
}

type ModelLegendProps = {
  byModel: Record<ModelId, number>;
};

export function ModelLegend({ byModel }: ModelLegendProps) {
  return (
    <ul className='grid grid-cols-2 gap-x-4 gap-y-2 @xl:grid-cols-4'>
      {MODELS.map((model) => (
        <li key={model.id} className='flex min-w-0 items-center gap-2'>
          <span
            aria-hidden='true'
            style={{ backgroundColor: seriesColorOf(model.series) }}
            className='size-2 shrink-0 rounded-full'
          />
          <BrandTile brand={model.brand} size='sm' />
          <span className='min-w-0 flex-1 truncate text-[13px]'>
            {model.name}
          </span>
          <MotionNumber
            value={byModel[model.id]}
            className='text-muted-foreground text-xs'
          />
        </li>
      ))}
    </ul>
  );
}

'use client';

import { motion, type Transition } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { EASE_OUT_STRONG, INSTANT } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';

import type { PeriodId } from './data';

const RISE_S = 0.6;

const STAGGER_S = 0.02;

function riseOf(shouldReduceMotion: boolean, index: number): Transition {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return { duration: RISE_S, ease: EASE_OUT_STRONG, delay: index * STAGGER_S };
}

function startOf(hasChanged: boolean, shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return false;
  }
  if (hasChanged) {
    return { scaleY: 0 };
  }
  return false;
}

function toneOf(isLatest: boolean) {
  if (isLatest) {
    return 'bg-primary';
  }
  return 'bg-primary/35';
}

function heightShareOf(value: number, tallest: number) {
  if (tallest <= 0) {
    return 0;
  }
  return value / tallest;
}

function tallestOf(values: readonly number[]) {
  return Math.max(1, ...values);
}

type DayChartProps = {
  periodId: PeriodId;
  values: readonly number[];
  labels: readonly string[];
  caption: string;
  hasChanged: boolean;
};

export function DayChart({
  periodId,
  values,
  labels,
  caption,
  hasChanged,
}: DayChartProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const initialOf = startOf(hasChanged, shouldReduceMotion);
  const tallest = tallestOf(values);
  const lastIndex = values.length - 1;

  return (
    <div className='relative flex flex-col gap-2'>
      <div aria-hidden='true' className='flex h-28 items-stretch gap-0.5'>
        {values.map((value, index) => (
          <span
            key={`${periodId}-${index}`}
            className='bg-foreground/[0.04] relative flex-1 overflow-hidden rounded-[3px]'
          >
            <motion.span
              initial={initialOf}
              animate={{ scaleY: heightShareOf(value, tallest) }}
              transition={riseOf(shouldReduceMotion, index)}
              className={cn(
                'absolute inset-0 origin-bottom',
                toneOf(index === lastIndex)
              )}
            />
          </span>
        ))}
      </div>
      <p
        aria-hidden='true'
        className='text-muted-foreground flex justify-between text-[11px] tabular-nums'
      >
        {labels.map((label) => (
          <span key={label}>{label}</span>
        ))}
      </p>
      <div className='sr-only'>
        <table>
          <caption>{caption}</caption>
          <tbody>
            {values.map((value, index) => (
              <tr key={index}>
                <th scope='row'>{index + 1}</th>
                <td>{value}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import { cn } from '@/registry/ndeko/lib/utils';

import { isNearLimit, LIMITS, shareOf, type Limit } from './data';

function meterToneOf(isNear: boolean) {
  if (isNear) {
    return 'bg-warning';
  }
  return 'bg-primary';
}

function figureToneOf(isNear: boolean) {
  if (isNear) {
    return 'text-warning-foreground';
  }
  return 'text-muted-foreground';
}

function figureTextOf(limit: Limit) {
  return `${limit.used} of ${limit.max}${limit.unit}`;
}

function LimitRow({ limit }: { limit: Limit }) {
  const share = shareOf(limit.used, limit.max);
  const isNear = isNearLimit(share);
  const open = 1 - share;
  const remaining = open * 100;
  const fillStyle = { transform: `translateX(-${remaining}%)` };

  return (
    <li className='flex flex-col gap-1.5'>
      <div className='flex items-baseline justify-between gap-3 text-[13px]'>
        <span className='min-w-0 truncate'>{limit.label}</span>
        <span className={cn('text-xs tabular-nums', figureToneOf(isNear))}>
          {figureTextOf(limit)}
          {isNear && <span className='sr-only'>, near the limit</span>}
        </span>
      </div>
      <div
        role='meter'
        aria-label={limit.label}
        aria-valuemin={0}
        aria-valuemax={limit.max}
        aria-valuenow={limit.used}
        className='bg-foreground/[0.06] h-1.5 overflow-hidden rounded-full'
      >
        <span
          style={fillStyle}
          className={cn('block h-full rounded-full', meterToneOf(isNear))}
        />
      </div>
    </li>
  );
}

export function LimitRows() {
  return (
    <ul className='flex flex-col gap-4'>
      {LIMITS.map((limit) => (
        <LimitRow key={limit.id} limit={limit} />
      ))}
    </ul>
  );
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';

import {
  periodOf,
  shareOf,
  USAGE,
  usedOf,
  percentOf,
  type PeriodId,
} from './data';

export type UsageState = {
  period: PeriodId;
  /** False until the first change: the bars are drawn full when the page loads and refill only after a change. */
  hasChanged: boolean;
  spoken: string;
};

export type UsageAction = { type: 'periodPicked'; period: PeriodId };

type Step = SessionStep<UsageState, UsageAction>;

export const INITIAL: UsageState = {
  period: 'month',
  hasChanged: false,
  spoken: '',
};

function spokenPeriodOf(id: PeriodId) {
  const usage = USAGE[id];
  const used = usedOf(usage);
  const share = shareOf(used, usage.limit);
  const percent = percentOf(share);
  const name = periodOf(id).spoken;
  return `Showing ${name}: ${used} of ${usage.limit} credits used, ${percent}%`;
}

function periodPicked(state: UsageState, period: PeriodId): UsageState {
  if (state.period === period) {
    return state;
  }
  return { period, hasChanged: true, spoken: spokenPeriodOf(period) };
}

export function reducer(state: UsageState, action: UsageAction): UsageState {
  switch (action.type) {
    case 'periodPicked':
      return periodPicked(state, action.period);
  }
}

function picks(after: number, period: PeriodId): Step {
  return {
    after,
    by: 'demo',
    press: `period-${period}`,
    action: { type: 'periodPicked', period },
  };
}

/** The month is where the block rests, so a round ends on it and the next one starts from it. */
export const SCRIPT: Step[] = [
  picks(2800, 'today'),
  picks(3000, 'week'),
  picks(3000, 'month'),
];

export const RESTING: UsageState = INITIAL;

export const LOOP_AFTER_MS = 3200;

import type { SeriesSlot } from '@/registry/ndeko/lib/agent-run';
import type { BrandSlug } from '@/registry/ndeko/lib/brand-logos';

export type PeriodId = 'today' | 'week' | 'month';

export type Period = {
  id: PeriodId;
  label: string;
  spoken: string;
  chartTitle: string;
  chartLabels: [string, string, string];
};

export const PERIODS: Period[] = [
  {
    id: 'today',
    label: 'Today',
    spoken: 'today',
    chartTitle: 'Credits by hour',
    chartLabels: ['00:00', '09:00', '17:00'],
  },
  {
    id: 'week',
    label: 'This week',
    spoken: 'this week',
    chartTitle: 'Credits by day',
    chartLabels: ['Mon', 'Wed', 'Fri'],
  },
  {
    id: 'month',
    label: 'This month',
    spoken: 'this month',
    chartTitle: 'Credits by day',
    chartLabels: ['Day 1', 'Day 7', 'Day 13'],
  },
];

export const WORKSPACE = { name: 'Kasai Freight', plan: 'Team plan' };

export type ModelId = 'claude' | 'gemini' | 'chatgpt' | 'mistral';

export type Model = {
  id: ModelId;
  name: string;
  brand: BrandSlug;
  series: SeriesSlot;
};

export const MODELS: Model[] = [
  { id: 'claude', name: 'Claude', brand: 'claude', series: 1 },
  { id: 'gemini', name: 'Gemini', brand: 'gemini', series: 2 },
  { id: 'chatgpt', name: 'ChatGPT', brand: 'openai', series: 3 },
  { id: 'mistral', name: 'Mistral', brand: 'mistral', series: 4 },
];

export type Usage = {
  limit: number;
  byModel: Record<ModelId, number>;
  chart: number[];
  upgrade: string | null;
};

/** Every figure is invented. For each period the credits by model and the bars add up to the same total. */
export const USAGE: Record<PeriodId, Usage> = {
  today: {
    limit: 250,
    byModel: { claude: 84, gemini: 46, chatgpt: 38, mistral: 12 },
    chart: [0, 0, 0, 0, 0, 0, 2, 6, 14, 22, 26, 20, 12, 18, 24, 20, 10, 6],
    upgrade: null,
  },
  week: {
    limit: 1400,
    byModel: { claude: 520, gemini: 290, chatgpt: 250, mistral: 90 },
    chart: [230, 260, 240, 240, 180],
    upgrade:
      'Four fifths of this week is used. Scale adds 10,000 credits a month',
  },
  month: {
    limit: 5000,
    byModel: { claude: 1980, gemini: 1150, chatgpt: 900, mistral: 320 },
    chart: [150, 470, 500, 480, 460, 420, 330, 390, 230, 260, 240, 240, 180],
    upgrade:
      'At this pace the credits run out in two days. Scale adds 10,000 credits a month',
  },
};

export const NEAR_LIMIT_SHARE = 0.8;

export type Limit = {
  id: string;
  label: string;
  used: number;
  max: number;
  unit: string;
};

export const LIMITS: Limit[] = [
  { id: 'agents', label: 'Agents', used: 4, max: 5, unit: '' },
  { id: 'seats', label: 'Seats', used: 9, max: 10, unit: '' },
  { id: 'apps', label: 'Connected apps', used: 7, max: 12, unit: '' },
  { id: 'files', label: 'Stored files', used: 3.2, max: 5, unit: ' GB' },
];

const FALLBACK_PERIOD = PERIODS[0];

export function periodOf(id: PeriodId) {
  const period = PERIODS.find((candidate) => candidate.id === id);
  return period ?? FALLBACK_PERIOD;
}

export function usedOf(usage: Usage) {
  let total = 0;
  for (const model of MODELS) {
    total += usage.byModel[model.id];
  }
  return total;
}

export function shareOf(used: number, limit: number) {
  if (limit <= 0) {
    return 0;
  }
  const share = used / limit;
  return Math.min(1, share);
}

export function isNearLimit(share: number) {
  return share >= NEAR_LIMIT_SHARE;
}

export function percentOf(share: number) {
  return Math.round(share * 100);
}
